/* Morning Deck for Friends service worker (generated by scripts/build-pages.js). Offline-first shell; never touches API calls. */
const VERSION = 'mdf-09769df711';
const SHELL = ["./","index.html","styles.css","friends.css","config.js","engine.js","services.js","parsers.js","connectors-free.js","connectors-oauth.js","connectors-inbox.js","app.js","ui.js","ui-setup.js","manifest.webmanifest","fonts/jakarta.woff2","icons/icon-192.png","icons/icon-512.png","icons/maskable-192.png","icons/maskable-512.png","icons/favicon-32.png","icons/apple-touch-icon.png"];
self.addEventListener('install', (e) => { e.waitUntil(caches.open(VERSION).then((c) => c.addAll(SHELL)).then(() => self.skipWaiting())); });
self.addEventListener('activate', (e) => {
  e.waitUntil(caches.keys().then((keys) => Promise.all(keys.filter((k) => k.startsWith('mdf-') && k !== VERSION).map((k) => caches.delete(k)))).then(() => self.clients.claim()));
});
// Same-origin app files only: network first (fresh when online), cache when offline or slow (4 s). Cross-origin requests
// (weather, Todoist, Google, ...) go straight to the network and are never cached here.
self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET' || !req.url.startsWith(self.registration.scope)) return;
  const key = req.mode === 'navigate' ? './' : req;
  e.respondWith(new Promise((resolve) => {
    let done = false;
    const fromCache = () => caches.match(key, { ignoreSearch: true }).then((r) => r || caches.match('./'));
    const timer = setTimeout(() => fromCache().then((r) => { if (r && !done) { done = true; resolve(r); } }), 4000);
    fetch(req).then((res) => {
      if (res.ok && res.type === 'basic') { const copy = res.clone(); caches.open(VERSION).then((c) => c.put(key, copy)); }
      clearTimeout(timer); if (!done) { done = true; resolve(res); }
    }).catch(() => { clearTimeout(timer); fromCache().then((r) => { if (!done) { done = true; resolve(r || new Response('Offline', { status: 503, headers: { 'Content-Type': 'text/plain' } })); } }); });
  }));
});
